<?php
require_once APPPATH . 'views/themes/skinora/_helpers.php';
$snSlug = $settings->store_slug ?? '';
$snHome = base_url('store/' . $snSlug);
$snImage = sn_image($product->item_image ?? '', 1100);
$snPrice = (float) ($product->effective_price ?? $product->sales_price ?? 0);
$snOld = (float) ($product->original_price ?? 0);
$snStock = (int) ($product->stock ?? 0);
$snType = $product->product_type ?? 'physical';
$snVariant = ($product->item_group ?? '') === 'Variants';
$snAvailable = $snVariant || $snType !== 'physical' || $snStock > 0 || !empty($settings->allow_backorder);
?>
<main class="sn-inner"><div class="container"><div class="sn-breadcrumb"><a href="<?= sn_e($snHome); ?>">Home</a><span>›</span><a href="<?= sn_e($snHome . '/products'); ?>">Shop</a><span>›</span><?= sn_e($product->item_name); ?></div><div class="sn-detail"><div class="sn-detail-image"><?php if ($snImage): ?><img id="sn-detail-image" src="<?= sn_e($snImage); ?>" alt="<?= sn_e($product->item_name); ?>"><?php else: ?><span class="sn-image-placeholder">SKINORA</span><?php endif; ?></div><div class="sn-detail-copy"><div class="eyebrow"><?= sn_e($product->category_name ?? 'THE SKINORA SELECTION'); ?></div><h1><?= sn_e($product->item_name); ?></h1><div class="sn-detail-price" id="sn-detail-price"><?= $snVariant && $snPrice <= 0 ? 'Choose an option' : sf_currency($snPrice, $store_currency ?? null); ?><?php if ($snOld > $snPrice && $snPrice > 0): ?><span class="old"><?= sf_currency($snOld, $store_currency ?? null); ?></span><?php endif; ?></div><p class="sn-detail-description"><?= nl2br(sn_e($product->description ?? '')); ?></p><div class="sn-availability"><?= $snAvailable ? 'Available to order' : 'Currently unavailable'; ?></div><?php $this->load->view('themes/shared/variant_picker', ['sf_picker_mode' => 'select']); ?><div class="sn-detail-buy"><div class="sn-quantity"><button type="button" id="sn-qty-minus" aria-label="Decrease quantity">−</button><span id="sn-qty">1</span><button type="button" id="sn-qty-plus" aria-label="Increase quantity">+</button></div><button type="button" class="btn" id="sn-detail-add" <?= $snAvailable ? '' : 'disabled'; ?>><?= $snAvailable ? 'ADD TO BAG ↗' : 'OUT OF STOCK'; ?></button></div><?php if (!$snAvailable) $this->load->view('themes/shared/restock_subscribe', ['sf_item_id' => $product->id]); ?><p class="sn-detail-note">Secure checkout · Beautifully considered care</p></div></div><?php if (!empty($related_products)): ?><section class="section sn-related"><div class="section-heading"><div><div class="eyebrow">COMPLETE YOUR ROUTINE</div><h2 class="section-title">You may also love.</h2></div><a class="text-link" href="<?= sn_e($snHome . '/products'); ?>">SHOP ALL ↗</a></div><div class="product-grid"><?php foreach (array_slice($related_products, 0, 4) as $related): if ((int) $related->id !== (int) $product->id) sn_product_card($related, $snSlug, $store_currency ?? null, $settings); endforeach; ?></div></section><?php endif; ?></div></main>
<script>(function(){var item=<?= json_encode(['id'=>(int)$product->id,'type'=>$snType,'name'=>$product->item_name,'price'=>$snPrice,'image'=>$product->item_image ?? '','stock'=>$snStock], JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT); ?>,itemType=item.type,qty=1,needsVariant=<?= $snVariant ? 'true' : 'false'; ?>;document.getElementById('sn-qty-minus').addEventListener('click',function(){qty=Math.max(1,qty-1);document.getElementById('sn-qty').textContent=qty});document.getElementById('sn-qty-plus').addEventListener('click',function(){qty++;document.getElementById('sn-qty').textContent=qty});document.addEventListener('sf:variant-picked',function(e){if(!e.detail)return;item=e.detail;var image=document.getElementById('sn-detail-image');if(image&&item.image)image.src='<?= base_url(); ?>'+item.image;document.getElementById('sn-detail-price').textContent=formatMoney(item.price);var button=document.getElementById('sn-detail-add');button.disabled=item.stock<=0&&!<?= !empty($settings->allow_backorder) ? 'true' : 'false'; ?>;button.textContent=button.disabled?'OUT OF STOCK':'ADD TO BAG ↗'});document.getElementById('sn-detail-add').addEventListener('click',function(){if(needsVariant&&!window.sfPickedVariant){showToast('Please choose an option first');return}var p=window.sfPickedVariant||item;addToCart(p.id,itemType,p.name,p.price,p.image,qty,p.stock)});if(typeof mpTrackEvent==='function')mpTrackEvent('view_item',item.id,item.price)})();</script>
